import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: ECM 문서 식별자는 'ECM-' 뒤에 웹 오피스 문서 ID를 붙여 만든다 (ECM 연계 규격 미확정).
const ECM_ID_PREFIX = 'ECM-';
// 가정: 문서 구분 값은 API 설명의 세 가지다.
const DOCUMENT_TYPES = ['작성 문서', '공유 문서', '공유받은 문서'];

// 가정: 기존 ECM 호출 규격이 없어 식별자를 정해 돌려준다. 호출이 실패하면 예외를 던진다.
async function saveToEcm(officeDocumentId: string): Promise<string> {
  return ECM_ID_PREFIX + officeDocumentId;
}

@Controller('api/v1')
export class FnSfr04107Controller {
  @Post('/office-documents/:officeDocumentId/link-ecm')
  @HttpCode(200)
  async linkOfficeDocumentToEcm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const officeDocumentId = req.params['officeDocumentId'];
    if (!/^[0-9]+$/.test(officeDocumentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID 형식이 올바르지 않습니다.');
    }
    const result = await transaction(async (db) => {
      const docs = await db.query(
        'SELECT office_document_id AS "officeDocumentId" FROM office_document WHERE office_document_id = CAST(:id AS bigint)',
        { id: officeDocumentId },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '연계할 문서가 존재하지 않습니다.');
      }
      let ecmId = '';
      let failure = '';
      try {
        ecmId = await saveToEcm(officeDocumentId);
      } catch (e) {
        failure = 'ECM 연계 호출이 실패했습니다.';
      }
      if (failure === '') {
        await db.execute(
          'UPDATE office_document SET ecm_document_id = :ecmId, updated_at = now() WHERE office_document_id = CAST(:id AS bigint)',
          { ecmId, id: officeDocumentId },
        );
        await db.query(
          'INSERT INTO link_log (requester_id, link_target, link_type, status, requested_at, completed_at, request_summary, processed_count, created_at, updated_at) ' +
            "VALUES (CAST(:userId AS bigint), 'ECM', '문서 저장', 'SUCCESS', now(), now(), :summary, 1, now(), now()) RETURNING link_log_id AS \"linkLogId\"",
          { userId: user.id, summary: 'office_document ' + officeDocumentId },
        );
        return { ok: true, ecmId };
      }
      await db.query(
        'INSERT INTO link_log (requester_id, link_target, link_type, status, requested_at, completed_at, failure_reason, request_summary, processed_count, created_at, updated_at) ' +
          "VALUES (CAST(:userId AS bigint), 'ECM', '문서 저장', 'FAILED', now(), now(), :reason, :summary, 0, now(), now()) RETURNING link_log_id AS \"linkLogId\"",
        { userId: user.id, reason: failure, summary: 'office_document ' + officeDocumentId },
      );
      return { ok: false, ecmId: '' };
    });
    if (!result.ok) {
      throw new ApiError(502, 'ECM_LINK_FAILED', 'ECM 연계에 실패했습니다. 잠시 뒤 다시 시도해 주세요.');
    }
    return { linked: true, ecmDocumentId: result.ecmId };
  }

  @Get('/ecm-documents')
  async listEcmDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const documentType = String(q['documentType'] ?? '');
    if (!DOCUMENT_TYPES.includes(documentType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 구분을 선택해 주세요.');
    }
    const keyword = String(q['keyword'] ?? '').trim();
    const pageRaw = Number(q['page'] ?? 0);
    const sizeRaw = Number(q['size'] ?? 20);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      let scope = '';
      if (documentType === '작성 문서') {
        scope = 'd.author_id = CAST(:userId AS bigint)';
      } else if (documentType === '공유 문서') {
        scope =
          'd.author_id = CAST(:userId AS bigint) AND EXISTS (SELECT 1 FROM office_document_share s WHERE s.office_document_id = d.office_document_id)';
      } else {
        scope =
          'EXISTS (SELECT 1 FROM office_document_share s WHERE s.office_document_id = d.office_document_id AND s.employee_id = CAST(:userId AS bigint))';
      }
      const where = 'd.ecm_document_id IS NOT NULL AND ' + scope + ' AND (:keyword = \'\' OR d.title ILIKE :pattern)';
      const params = { userId: user.id, keyword, pattern: '%' + keyword + '%' };
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM office_document d WHERE ' + where, params);
      const items = await db.query(
        'SELECT d.office_document_id AS "officeDocumentId", d.title AS "title", d.ecm_document_id AS "ecmDocumentId", d.author_id AS "authorId" ' +
          'FROM office_document d WHERE ' +
          where +
          ' ORDER BY d.office_document_id DESC LIMIT :limit OFFSET :offset',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }
}

