import { useState } from 'react';
import {
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['작성 문서', '작성 문서'],
  ['공유 문서', '공유 문서'],
  ['공유받은 문서', '공유받은 문서'],
];

export default function FnSfr04107Page({ role, notify }: PageProps) {
  const [documentType, setDocumentType] = useState('작성 문서');
  const [keyword, setKeyword] = useState('');
  const [applied, setApplied] = useState({ documentType: '작성 문서', keyword: '' });
  const [pageNo, setPageNo] = useState(0);
  const [linking, setLinking] = useState(false);
  const [target, setTarget] = useState<number | string>('');

  const { data, error, reload } = useData<Page>(
    () =>
      call<Page>('GET', '/ecm-documents', role, undefined, {
        documentType: applied.documentType,
        keyword: applied.keyword,
        page: pageNo,
        size: 20,
      }),
    [applied, pageNo, role],
  );

  const search = () => {
    setPageNo(0);
    setApplied({ documentType, keyword });
  };

  const reset = () => {
    setDocumentType('작성 문서');
    setKeyword('');
    setPageNo(0);
    setApplied({ documentType: '작성 문서', keyword: '' });
  };

  const link = async () => {
    if (target === '') {
      throw new Error('ECM에 연계할 문서를 선택해 주세요.');
    }
    await call('POST', `/office-documents/${target}/link-ecm`, role, {});
    notify('ECM에 연계했습니다.');
    setLinking(false);
    setTarget('');
    reload();
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>ECM 문서 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="문서 구분" required>
            <Select value={documentType} onChange={setDocumentType} options={TYPE_OPTIONS} />
          </Field>
          <Field label="ECM 문서 조회 조건">
            <TextInput value={keyword} onChange={setKeyword} placeholder="문서 제목" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={() => setLinking(true)}>웹 오피스 문서 ECM 연계</button>
        </Band>
        {error !== '' && <p>{error}</p>}
        <DataTable
          columns={[
            { key: 'title', label: '문서 제목' },
            { key: 'ecmDocumentId', label: 'ECM 문서 식별자' },
            {
              key: 'authorId',
              label: '작성자',
              render: (row: Row) => <RefName table="employee" role={role} value={row['authorId']} />,
            },
          ]}
          rows={data?.items ?? []}
          empty="조건에 맞는 ECM 문서가 없습니다. 조건을 바꿔 다시 조회해 주세요."
        />
        <Pager page={pageNo} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {linking && (
        <Drawer title="웹 오피스 문서 ECM 연계" onClose={() => setLinking(false)}>
          <Form
            onSubmit={link}
            submit="ECM에 연계 저장"
            note="선택한 문서를 기존 ECM에 저장하고 연계 이력을 남깁니다."
          >
            <Field label="웹 오피스 문서 ID" required wide>
              <LookupSelect
                table="office_document"
                role={role}
                value={target}
                onChange={setTarget}
                placeholder="문서 선택"
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
